#!/bin/bash
set -e
TOOL=/tmp/bench68684356/bin/pod-ready
KCONF=/var/lib/bench68684356/kubelet/config.yaml
GATE=/var/lib/bench68684356/gate
echo '[solution] gate: the file its probe tests; steady and never: what their probes do'
cat > "$TOOL" <<'EOF'
#!/bin/bash
case "$1" in
    gate-node1) [ -f /var/lib/bench68684356/gate/open ] && echo true || echo false ;;
    steady-node1) echo true ;;
    never-node1) echo false ;;
    *) echo "no such pod" >&2; exit 1 ;;
esac
EOF
chmod 755 "$TOOL"

